package com.finance.tracker.business.domain

import kotlin.io.encoding.Base64
import kotlin.test.*

class CashXlsxFormulaBoundaryTest {
    // Synthetic OOXML: numeric formula cache is 20; the plain-string control contains a literal '='.
    private val files = mapOf(
        "normal" to "",
        "shared" to "",
        "shared-follower" to "",
        "array" to "",
        "data-table" to "",
        "text" to "",
    )
    @Test fun formulasNeverFallBackToCachedNumbersOrPartialStatementRows() {
        for ((kind, encoded) in files) if (kind != "text") {
            val bytes = Base64.decode(encoded)
            val before = bytes.copyOf()
            assertEquals("statement_unreadable", assertFailsWith<StatementDocumentFailure>(kind) {
                readLocalCashXlsxDocument(bytes, "wechat")
            }.code)
            assertContentEquals(before, bytes)
        }
    }
    @Test fun anEqualsPrefixInAPlainStringIsPreserved() {
        val document = readLocalCashXlsxDocument(Base64.decode(files.getValue("text")), "wechat")
        assertEquals(1, document.rows.size)
        assertEquals("20", document.rows.single().payload?.get("金额(元)"))
        assertEquals("=SUM(A1:B2)", document.rows.single().payload?.get("商品"))
    }
}
